import os, sys; sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "lib"))
import sys, json, time, os, re, base64, hashlib, subprocess, shutil, urllib.request
from harness import *
import harness
harness.TEST_MSG = None; harness.TEST_LANG = None      # the language is chosen by the setting, as in a real installation
WEB = "/data/Transmission/transmission/web"; GM = "/data/Transmission/guard_messages.txt"; LD = "/data/Transmission/locales"
TOOLS = REPO
def meta(name): return base64.b64encode(bencode({"announce": "http://127.0.0.1:1/announce", "info": {"name": name, "length": 65536, "piece length": 65536, "pieces": hashlib.sha1(name.encode()).digest()}})).decode()
def setcfg(**kw): return api("POST", "/api/config", kw)
def refuse(name): return rpc("torrent-add", metainfo=meta(name), **{"download-dir": "/mnt/ext1/not_in_list"})   # the folder is not in the list: the daemon refuses and substitutes the path ({1})
def lang_js(): return open(f"{WEB}/ps5-lang.js", encoding="utf-8").read()
def served(): return urllib.request.urlopen("http://127.0.0.1:9091/transmission/web/ps5-lang.js", timeout=5).read().decode("utf-8")
def node(lang):
    shutil.copy(f"{WEB}/ps5-lang.js", f"/tmp/i18n_{lang}.js")
    r = subprocess.run(["node", "i18n_web_test.js", lang, f"/tmp/i18n_{lang}.js", WEB], cwd=WEB_TESTS, capture_output=True, text=True, timeout=60)
    m = re.search(r"(\d+)/(\d+) web translation checks passed", r.stdout)
    return r, (int(m.group(1)), int(m.group(2))) if m else (0, 0)
shutil.rmtree(LD, ignore_errors=True)
fresh(); loader = Loader(); m = start_manager()
try:
    wait(lambda: daemon_pids() and rpc_ok() and dstate()["state"] == "running", 70); time.sleep(4)
    idx = urllib.request.urlopen("http://127.0.0.1:9091/transmission/web/", timeout=5).read().decode()
    check("the web client page loads the dictionary and the translator before the app; the marked texts are in index.html (data-i18n)", idx.index("ps5-lang.js") < idx.index("ps5-i18n.js") < idx.index("ps5-compat.js") < idx.index("transmission-app.js") and idx.count("data-i18n") >= 14, idx.count("data-i18n"))
    app = open(f"{WEB}/transmission-app.js", encoding="utf-8").read()
    check("the translation is INSIDE the client code: over 250 calls ps5t(...), the plural words go through ps5n, nothing searches the page", app.count("ps5t(") > 250 and 'ps5n("{1} "+e' in app and "MutationObserver" not in open(f"{WEB}/ps5-i18n.js", encoding="utf-8").read(), app.count("ps5t("))
    r = subprocess.run(["node", f"{TOOLS}/tools/web-i18n-check.js", f"{TOOLS}/locales/ru.strings", f"{TOOLS}/locales/en.strings", WEB], capture_output=True, text=True)
    check("every English key that the client code and our files ask for exists in the language tables (nothing falls through silently)", r.returncode == 0, r.stdout[-300:])
    setcfg(language="ru"); time.sleep(1.5); js = lang_js()
    check("RU: ps5-lang.js is rewritten at once (lang ru, Russian plural rules), the daemon serves the same text; the key is the English text itself", 'lang:"ru"' in js and 'plural:"ru"' in js and served() == js and '"Open torrent…":"Открыть торрент…"' in js and '"{1} peers":"{1} пир|{1} пира|{1} пиров"' in js, js[:90])
    r = refuse("w_one")
    check("RU: the refusal of the daemon is in Russian, with the path put in", "Папки «/mnt/ext1/not_in_list» нет в списке папок загрузок" in r["result"], r["result"][:90])
    gm = open(GM, encoding="utf-8").read()
    check("RU: guard_messages.txt has the lines (English format, a tab, the translation with {1})", "The drive %s is not connected: the torrent was not added.\tДиск {1} не подключён: торрент не добавлен." in gm, gm[:100])
    rr, (ok, tot) = node("ru"); print(rr.stdout.strip().split("\n")[-1])
    check("RU: ps5t, ps5n and the marked index.html work on the real files (jsdom)", tot > 0 and ok == tot, rr.stdout[-500:])
    setcfg(language="en"); time.sleep(1.5); js = lang_js()
    check("EN: the dictionary is empty (the English key is the text) and the language is en", 'lang:"en"' in js and 'map:{}' in js, js[:90])
    r = refuse("w_two")
    check("EN: the refusal is English and guard_messages.txt is empty (the daemon uses its own text)", "The folder '/mnt/ext1/not_in_list' is not in the list of download folders" in r["result"] and os.path.getsize(GM) == 0, (r["result"][:60], os.path.getsize(GM)))
    rr, (ok, tot) = node("en"); print(rr.stdout.strip().split("\n")[-1])
    check("EN: the real files give English everywhere (jsdom)", tot > 0 and ok == tot, rr.stdout[-400:])
    os.makedirs(LD, exist_ok=True)
    open(f"{LD}/xx.strings", "w", encoding="utf-8").write('"LanguageName" = "XX"\n"Open" = "Abrir"\n"{1} ago" = "hace {2}"\n"me_g_not_in_list" = "Carpeta «{1}» no esta en la lista."\n')
    c, t = setcfg(language="file:xx.strings")
    check("a file whose template uses a placeholder the English text does not have ({2} in '{1} ago') is refused", c == 400 and "LANGERR:ph:" in t and "ago" in t, t[:100])
    open(f"{LD}/xx.strings", "w", encoding="utf-8").write('"LanguageName" = "XX"\n"Open" = "Abrir"\n"{1} ago" = "hace {1}"\n"me_g_not_in_list" = "Carpeta «{1}» no esta en la lista."\n')
    c, t = setcfg(language="file:xx.strings"); time.sleep(1.5); js = lang_js()
    check("FILE: accepted; the dictionary has exactly the file's keys ('Open', '{1} ago'), keys it lacks are simply not there (the English key stays)", c == 200 and '"Open":"Abrir"' in js and '"{1} ago":"hace {1}"' in js and '"Close":' not in js, (c, js[:100]))
    r = refuse("w_three")
    check("FILE: the daemon refusal uses the file's text", "Carpeta «/mnt/ext1/not_in_list» no esta en la lista." in r["result"], r["result"][:80])
    rr, (ok, tot) = node("xx"); print(rr.stdout.strip().split("\n")[-1])
    check("FILE: the real files work with a partial file (jsdom)", tot > 0 and ok == tot, rr.stdout[-400:])
    setcfg(language="ru"); time.sleep(1.5)
    check("choosing Russian again restores the Russian dictionary (no leftovers of the file)", "Abrir" not in lang_js() and 'lang:"ru"' in lang_js(), None)
finally:
    kill_all(); shutil.rmtree(LD, ignore_errors=True)
    try: loader.close()
    except Exception: pass
sys.exit(summary())
